using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace DigitalEvidenceSystem.Web.Pages.Evidence;
[Authorize] public sealed class IndexModel(EvidenceDbContext db):PageModel { public List<EvidenceItem> Items{get;set;}=[]; public string? Query{get;set;} public string? Status{get;set;} public string? Type{get;set;} public string[] Statuses=>["Received","In Examination","Reviewed","Released"]; public string[] Types=>["Mobile phone","Computer","Hard drive","USB drive","Memory card","Image","Video","Audio","Document","Network capture","Other"]; public async Task OnGetAsync(string? q,string? status,string? type){Query=q?.Trim();Status=status;Type=type;var items=db.Evidence.Include(e=>e.CaseFile).AsQueryable();if(!string.IsNullOrWhiteSpace(Query))items=items.Where(e=>e.EvidenceNumber.Contains(Query)||e.Name.Contains(Query)||e.SourceDevice.Contains(Query)||e.CurrentCustodian.Contains(Query));if(!string.IsNullOrWhiteSpace(Status))items=items.Where(e=>e.Status==Status);if(!string.IsNullOrWhiteSpace(Type))items=items.Where(e=>e.Type==Type);Items=await items.OrderByDescending(e=>e.CollectedOn).ToListAsync();}}